conv3d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv3d_kernel(const float* input, const int out_channels,
                               const int in_channels, const int kernel_size,
                               const int stride, const int padding, const int dilation,
                               const int groups, float* output,
                               int batch_size, int in_h, int in_w, int in_d,
                               int out_h, int out_w, int out_d) {
    long total_elements = batch_size * out_channels * out_h * out_w * out_d;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Decompose linear index
        int b = idx / (out_channels * out_h * out_w * out_d);
        int rem = idx % (out_channels * out_h * out_w * out_d);
        int oc = rem / (out_h * out_w * out_d);
        rem = rem % (out_h * out_w * out_d);
        int iw = rem / (out_w * out_d);
        rem = rem % (out_w * out_d);
        int id = rem / out_d;
        rem = rem % out_d;

        // Compute input offset for channel oc and kernel position
        long input_offset = ((b * in_channels + oc) * in_h * in_w * in_d +
                             (oc * out_h + iw * out_w + id * out_d) *
                              dilation * (kernel_size / 2 - 1) + padding)
                           * stride;

        float sum = 0.0f;
        for (int ic = 0; ic < in_channels; ++ic) {
            long input_offset_ic = ((b * in_channels + ic) * in_h * in_w * in_d +
                                    (oc * out_h + iw * out_w + id * out_d) *
                                     dilation * (kernel_size / 2 - 1) + padding)
                                   * stride;
            for (int ky = 0; ky < kernel_size; ++ky) {
                for (int kx = 0; kx < kernel_size; ++kx) {
                    for (int kz = 0; kz < kernel_size; ++kz) {
                        int input_idx = input_offset_ic + (ky * in_w + kx) * in_d;
                        sum += input[input_idx];
                    }
                }
            }
        }
        output[idx] = sum;
    }
}

torch::Tensor conv3d_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    // Parameters needed for the kernel – these match ModelNew's init arguments.
