        out.data_ptr<float>(),
        in_channels,
        kernel_size,
        stride,
        padding,
        dilation,
        groups,
        out.data_ptr<float>(),
        x.size(0), # batch size
        x.size(1), # height (in_h)
        x.size(2), # width (in_w)
        x.size(3)  # depth (in_d)
    );

    return out;
}
